1	#pragma once
2	#include "itch_parser.hpp"
3	#include "order_book_flat.hpp"
4	#include <cstdint>
5	#include <vector>
6	
7	// Per-book-update microstructure signals: Order Flow Imbalance (OFI) and
8	// microprice (plan: .claude/plans/microstructure-signals.md, steps 2-3).
9	//
10	// Design note: this wraps OrderBookFlat rather than adding fields to it, so
11	// the book keeps a single responsibility and its latency benchmarks stay
12	// comparable with docs/perf/01-flat-book.md. The engine applies each parsed
13	// message to the book, snapshots top-of-book, and emits one MicroEvent per
14	// update.
15	//
16	// OFI follows the best-level definition of Cont, Kukanov & Stoikov (2014),
17	// "The Price Impact of Order Book Events": with best bid (P_b, q_b) and best
18	// ask (P_a, q_a), the event-n contribution is
19	//
20	//   e_n =  1{P_b_n >= P_b_{n-1}} * q_b_n  -  1{P_b_n <= P_b_{n-1}} * q_b_{n-1}
21	//        - 1{P_a_n <= P_a_{n-1}} * q_a_n  +  1{P_a_n >= P_a_{n-1}} * q_a_{n-1}
22	//
23	// Positive e_n = net buying pressure (bid depth added, ask depth consumed).
24	//
25	// Microprice is the depth-weighted mid: with imbalance I = q_b / (q_b + q_a),
26	//   microprice = I * P_a + (1 - I) * P_b
27	// It leans toward the side with LESS depth's price being hit next — a better
28	// short-horizon fair-value estimate than the plain mid.
29	
30	namespace itch {
31	
32	struct MicroEvent {
33	    uint64_t timestamp_ns;   // ITCH ns-since-midnight of the triggering message
34	    double   ofi;            // per-event OFI increment e_n, in shares (signed)
35	    double   microprice;     // depth-weighted mid, in dollars
36	    double   best_bid;       // dollars
37	    double   best_ask;       // dollars
38	    uint32_t bid_size;       // shares at best bid
39	    uint32_t ask_size;       // shares at best ask
40	};
41	
42	class MicrostructureEngine {
43	public:
44	    // Same construction contract as OrderBookFlat: the instrument's expected
45	    // fixed-point tick range must be declared up front.
46	    MicrostructureEngine(uint32_t min_price_raw, uint32_t max_price_raw,
47	                         uint32_t tick_size = 1)
48	        : book_(min_price_raw, max_price_raw, tick_size) {}
49	
50	    void on_add(const AddOrder& m) {
51	        book_.add(m.order_ref, m.side, m.price, m.shares);
52	        emit(m.timestamp_ns);
53	    }
54	    void on_execute(const ExecuteOrder& m) {
55	        book_.execute(m.order_ref, m.executed_shares);
56	        emit(m.timestamp_ns);
57	    }
58	    void on_delete(const DeleteOrder& m) {
59	        book_.del(m.order_ref);
60	        emit(m.timestamp_ns);
61	    }
62	    void on_replace(const ReplaceOrder& m) {
63	        book_.replace(m.old_order_ref, m.new_order_ref, m.shares, m.price);
64	        emit(m.timestamp_ns);
65	    }
66	
67	    // Ready-made visitor for parse_buffer(); the engine must outlive it.
68	    MessageVisitor visitor() {
69	        MessageVisitor v;
70	        v.on_add     = [this](const AddOrder& m)     { on_add(m); };
71	        v.on_execute = [this](const ExecuteOrder& m) { on_execute(m); };
72	        v.on_delete  = [this](const DeleteOrder& m)  { on_delete(m); };
73	        v.on_replace = [this](const ReplaceOrder& m) { on_replace(m); };
74	        return v;
75	    }
76	
77	    const std::vector<MicroEvent>& events() const { return events_; }
78	    // Updates while one book side was empty: no event can be computed there.
79	    uint64_t skipped_one_sided() const { return skipped_one_sided_; }
80	    const OrderBookFlat& book() const { return book_; }
81	
82	private:
83	    void emit(uint64_t timestamp_ns) {
84	        const TopOfBook tob = book_.top_of_book();
85	        if (!tob.best_bid || !tob.best_ask) {
86	            // A one-sided book has no spread: neither OFI's best-level deltas
87	            // nor microprice are defined. Count and move on; prev_* keeps the
88	            // last two-sided state so OFI resumes coherently.
89	            ++skipped_one_sided_;
90	            return;
91	        }
92	        const uint32_t bid_raw = tob.best_bid->price_raw;
93	        const uint32_t ask_raw = tob.best_ask->price_raw;
94	        const uint32_t q_b     = tob.best_bid->shares;
95	        const uint32_t q_a     = tob.best_ask->shares;
96	
97	        double e = 0.0;
