#pragma once
#include "order_book.hpp"  // re-uses OrderRecord, PriceLevel, TopOfBook
#include <cstdint>
#include <unordered_map>
#include <vector>
#include <stdexcept>
#include <algorithm>

// Optimised order book: price levels stored in a flat contiguous array
// indexed by (price_raw - min_price_raw) / tick_size.
//
// This replaces the hash-map baseline's std::map<price, shares> with a
// vector<uint32_t> where index == price tick.  The tradeoffs are:
//   + O(1) level lookup and update (vs O(log n) for std::map).
//   + Sequential memory layout — best-bid/ask scan is a cache-friendly
//     linear sweep over a small array.
//   - Fixed price range: [min_price_raw, max_price_raw] must be declared
//     at construction.  Out-of-range prices increment error_count.
//
// The public interface is identical to OrderBook so the bench driver needs
// no changes — just swap the type.

namespace itch {

class OrderBookFlat {
public:
    // min_price_raw / max_price_raw: inclusive bounds of the instrument's
    // expected tick range (in ITCH fixed-point units, i.e. price * 10000).
    // tick_size: granularity (default 1 = minimum ITCH resolution).
    //
    // Example for a stock trading $90–$110 with 0.0001 resolution:
    //   OrderBookFlat book(900000, 1100000, 1);
    OrderBookFlat(uint32_t min_price_raw, uint32_t max_price_raw, uint32_t tick_size = 1)
        : min_price_(min_price_raw)
        , max_price_(max_price_raw)
        , tick_size_(tick_size)
    {
        if (max_price_raw <= min_price_raw)
            throw std::invalid_argument("max_price_raw must be > min_price_raw");
        if (tick_size == 0)
            throw std::invalid_argument("tick_size must be > 0");
        const std::size_t n = (max_price_raw - min_price_raw) / tick_size + 1;
        bid_levels_.assign(n, 0);
        ask_levels_.assign(n, 0);
    }

    void add(uint64_t order_ref, char side, uint32_t price_raw, uint32_t shares) {
        if (orders_.count(order_ref)) { ++error_count_; return; }
        const std::size_t idx = _index(price_raw);
        if (idx == INVALID) { ++error_count_; return; }
        orders_[order_ref] = {side, price_raw, shares};
        _levels(side)[idx] += shares;
    }

    uint32_t execute(uint64_t order_ref, uint32_t executed_shares) {
        auto it = orders_.find(order_ref);
        if (it == orders_.end()) { ++error_count_; return 0; }
        OrderRecord& rec = it->second;
        const uint32_t to_remove = std::min(executed_shares, rec.shares);
        _remove_level(rec.side, rec.price_raw, to_remove);
        rec.shares -= to_remove;
        if (rec.shares == 0) orders_.erase(it);
        return to_remove;
    }

    bool del(uint64_t order_ref) {
        auto it = orders_.find(order_ref);
        if (it == orders_.end()) { ++error_count_; return false; }
        const OrderRecord& rec = it->second;
        _remove_level(rec.side, rec.price_raw, rec.shares);
        orders_.erase(it);
        return true;
    }

    void replace(uint64_t old_ref, uint64_t new_ref, uint32_t shares, uint32_t price_raw) {
        auto it = orders_.find(old_ref);
        if (it == orders_.end()) { ++error_count_; return; }
        const char side = it->second.side;
        _remove_level(side, it->second.price_raw, it->second.shares);
        orders_.erase(it);
        add(new_ref, side, price_raw, shares);
    }

    TopOfBook top_of_book() const {
        TopOfBook tob;
        // Best bid: highest price index with non-zero shares.
        for (std::size_t i = bid_levels_.size(); i-- > 0;) {
            if (bid_levels_[i] > 0) {
                tob.best_bid = PriceLevel{
                    min_price_ + static_cast<uint32_t>(i) * tick_size_,
                    bid_levels_[i]
                };
                break;
            }
        }
        // Best ask: lowest price index with non-zero shares.
        for (std::size_t i = 0; i < ask_levels_.size(); ++i) {
            if (ask_levels_[i] > 0) {
                tob.best_ask = PriceLevel{
                    min_price_ + static_cast<uint32_t>(i) * tick_size_,
                    ask_levels_[i]
                };
                break;
            }
        }
        return tob;
    }

    uint64_t error_count() const { return error_count_; }
    std::size_t order_count() const { return orders_.size(); }

private:
    static constexpr std::size_t INVALID = SIZE_MAX;

    uint32_t min_price_;
    uint32_t max_price_;
    uint32_t tick_size_;

    std::unordered_map<uint64_t, OrderRecord> orders_;
    std::vector<uint32_t> bid_levels_;
    std::vector<uint32_t> ask_levels_;
    uint64_t error_count_ = 0;

    std::size_t _index(uint32_t price_raw) const {
        if (price_raw < min_price_ || price_raw > max_price_) return INVALID;
        return (price_raw - min_price_) / tick_size_;
    }

    std::vector<uint32_t>& _levels(char side) {
        return (side == 'B') ? bid_levels_ : ask_levels_;
    }

    void _remove_level(char side, uint32_t price_raw, uint32_t shares) {
        const std::size_t idx = _index(price_raw);
        if (idx == INVALID) { ++error_count_; return; }
        auto& lv = (side == 'B') ? bid_levels_[idx] : ask_levels_[idx];
        if (lv <= shares) lv = 0;
        else lv -= shares;
    }
};

}  // namespace itch

