#include <gtest/gtest.h>
#include "../itch/itch_parser.hpp"
#include "../itch/order_book.hpp"
#include "../itch/signal.hpp"

#include <cstdint>
#include <cstring>
#include <vector>

// ─── ITCH message builder helpers ────────────────────────────────────────────

static void put_be16(uint8_t* p, uint16_t v) {
    p[0] = (v >> 8) & 0xff;
    p[1] =  v       & 0xff;
}
static void put_be32(uint8_t* p, uint32_t v) {
    p[0] = (v >> 24) & 0xff;
    p[1] = (v >> 16) & 0xff;
    p[2] = (v >>  8) & 0xff;
    p[3] =  v        & 0xff;
}
static void put_be64(uint8_t* p, uint64_t v) {
    put_be32(p,     static_cast<uint32_t>(v >> 32));
    put_be32(p + 4, static_cast<uint32_t>(v));
}

// Build a framed ITCH Add Order message ('A', 36 bytes payload).
// Frame = 2-byte big-endian length + payload.
static std::vector<uint8_t> make_add(uint64_t ref, char side, uint32_t shares, uint32_t price) {
    std::vector<uint8_t> buf(2 + 36, 0);
    put_be16(buf.data(), 36);
    buf[2] = 'A';
    put_be64(buf.data() + 2 + 11, ref);
    buf[2 + 19] = static_cast<uint8_t>(side);
    put_be32(buf.data() + 2 + 20, shares);
    put_be32(buf.data() + 2 + 32, price);
    return buf;
}

// Execute Order ('E', 31 bytes payload).
static std::vector<uint8_t> make_execute(uint64_t ref, uint32_t shares) {
    std::vector<uint8_t> buf(2 + 31, 0);
    put_be16(buf.data(), 31);
    buf[2] = 'E';
    put_be64(buf.data() + 2 + 11, ref);
    put_be32(buf.data() + 2 + 19, shares);
    return buf;
}

// Delete Order ('D', 19 bytes payload).
static std::vector<uint8_t> make_delete(uint64_t ref) {
    std::vector<uint8_t> buf(2 + 19, 0);
    put_be16(buf.data(), 19);
    buf[2] = 'D';
    put_be64(buf.data() + 2 + 11, ref);
    return buf;
}

// Concatenate a list of framed messages.
static std::vector<uint8_t> cat(std::initializer_list<std::vector<uint8_t>> msgs) {
    std::vector<uint8_t> out;
    for (const auto& m : msgs) out.insert(out.end(), m.begin(), m.end());
    return out;
}

// ─── Parser tests ────────────────────────────────────────────────────────────

TEST(ITCHParser, CountsAddMessages) {
    auto buf = make_add(1, 'B', 100, 1000000);
    itch::ParseStats stats = itch::parse_buffer(buf.data(), buf.size(), {});
    EXPECT_EQ(stats.add_count, 1u);
    EXPECT_EQ(stats.error_count, 0u);
}

TEST(ITCHParser, CountsExecuteMessages) {
    auto buf = cat({make_add(1, 'B', 100, 1000000), make_execute(1, 50)});
    itch::ParseStats stats = itch::parse_buffer(buf.data(), buf.size(), {});
    EXPECT_EQ(stats.add_count, 1u);
    EXPECT_EQ(stats.execute_count, 1u);
}

TEST(ITCHParser, SkipsUnknownMessageTypes) {
    // Insert a 'S' (System Event) message with length 12. Parser should skip it.
    std::vector<uint8_t> sys(2 + 12, 0);
    put_be16(sys.data(), 12);
    sys[2] = 'S';
    auto buf = cat({sys, make_add(2, 'S', 50, 2000000)});
    itch::ParseStats stats = itch::parse_buffer(buf.data(), buf.size(), {});
    EXPECT_EQ(stats.skipped_count, 1u);
    EXPECT_EQ(stats.add_count, 1u);
}

TEST(ITCHParser, HandlesTruncatedBuffer) {
    // Give it half of an Add Order message.
    auto full = make_add(1, 'B', 100, 1000000);
    full.resize(full.size() / 2);
    itch::ParseStats stats = itch::parse_buffer(full.data(), full.size(), {});
    EXPECT_GE(stats.error_count, 0u);  // at worst an error, never a crash
}

// ─── OrderBook tests ─────────────────────────────────────────────────────────

TEST(OrderBook, AddThenTopOfBook) {
    itch::OrderBook book;
    book.add(1, 'B', 1000000, 100);  // bid @ 100.0000, 100 shares
    book.add(2, 'S', 1010000, 200);  // ask @ 101.0000, 200 shares

    auto tob = book.top_of_book();
    ASSERT_TRUE(tob.best_bid.has_value());
    ASSERT_TRUE(tob.best_ask.has_value());
    EXPECT_EQ(tob.best_bid->price_raw, 1000000u);
    EXPECT_EQ(tob.best_bid->shares,    100u);
    EXPECT_EQ(tob.best_ask->price_raw, 1010000u);
    EXPECT_EQ(tob.best_ask->shares,    200u);
}

TEST(OrderBook, AddExecuteDeleteSequence) {
    // Scenario: add bid 100 shares @ 100.00, execute 60, then delete the rest.
    itch::OrderBook book;
    book.add(10, 'B', 1000000, 100);

    uint32_t filled = book.execute(10, 60);
    EXPECT_EQ(filled, 60u);
    EXPECT_EQ(book.order_count(), 1u);  // partial fill — order still live

    auto tob = book.top_of_book();
    ASSERT_TRUE(tob.best_bid.has_value());
    EXPECT_EQ(tob.best_bid->shares, 40u);  // 100 - 60

    bool removed = book.del(10);
    EXPECT_TRUE(removed);
    EXPECT_EQ(book.order_count(), 0u);

    tob = book.top_of_book();
    EXPECT_FALSE(tob.best_bid.has_value());
}

TEST(OrderBook, MultiLevelBidOrdering) {
    itch::OrderBook book;
    book.add(1, 'B', 990000, 50);
    book.add(2, 'B', 1000000, 75);  // highest bid — should be best
    book.add(3, 'B', 980000, 30);

    auto tob = book.top_of_book();
    ASSERT_TRUE(tob.best_bid.has_value());
    EXPECT_EQ(tob.best_bid->price_raw, 1000000u);
}

TEST(OrderBook, DeleteUnknownOrderIncrementsErrorCount) {
    itch::OrderBook book;
    bool ok = book.del(999);  // non-existent order
    EXPECT_FALSE(ok);
    EXPECT_EQ(book.error_count(), 1u);
}

