TEST(Signal, ValidSignalWithBothSides) {
    itch::OrderBook book;
    book.add(1, 'B', 1000000, 100);  // bid @ 100.0000
    book.add(2, 'S', 1010000, 50);   // ask @ 101.0000

    auto sig = itch::make_signal(book);
    EXPECT_TRUE(sig.valid);
    EXPECT_NEAR(sig.bid_price, 100.0, 1e-4);
    EXPECT_NEAR(sig.ask_price, 101.0, 1e-4);
    EXPECT_NEAR(sig.mid,      100.5, 1e-4);
}

TEST(Signal, InvalidSignalOneSide) {
    itch::OrderBook book;
    book.add(1, 'B', 1000000, 100);  // only bids, no asks

    auto sig = itch::make_signal(book);
    EXPECT_FALSE(sig.valid);
}

// ─── Integration: full Add → Execute → Delete sequence ───────────────────────

TEST(Integration, AddExecuteDeleteViaParser) {
    // Build a buffer: add bid, add ask, execute half of bid, delete rest.
    uint32_t bid_price = 1000000;  // 100.0000
    uint32_t ask_price = 1010000;  // 101.0000

    auto buf = cat({
        make_add(1, 'B', 200, bid_price),
        make_add(2, 'S', 300, ask_price),
        make_execute(1, 100),
        make_delete(1),
    });

    itch::OrderBook book;
    itch::MessageVisitor visitor;
    visitor.on_add     = [&](const itch::AddOrder& m)     { book.add(m.order_ref, m.side, m.price, m.shares); };
    visitor.on_execute = [&](const itch::ExecuteOrder& m)  { book.execute(m.order_ref, m.executed_shares); };
    visitor.on_delete  = [&](const itch::DeleteOrder& m)   { book.del(m.order_ref); };
    visitor.on_replace = [&](const itch::ReplaceOrder& m)  { book.replace(m.old_order_ref, m.new_order_ref, m.shares, m.price); };

    itch::ParseStats stats = itch::parse_buffer(buf.data(), buf.size(), visitor);
    EXPECT_EQ(stats.add_count,     2u);
    EXPECT_EQ(stats.execute_count, 1u);
    EXPECT_EQ(stats.delete_count,  1u);
    EXPECT_EQ(stats.error_count,   0u);

    // After execute(100) + delete, the bid side should be empty.
    // Ask side should still have 300 shares at ask_price.
    auto tob = book.top_of_book();
    EXPECT_FALSE(tob.best_bid.has_value());
    ASSERT_TRUE(tob.best_ask.has_value());
    EXPECT_EQ(tob.best_ask->price_raw, ask_price);
    EXPECT_EQ(tob.best_ask->shares,    300u);
}

