        make_add(1, 'B', 100, 1000000),
        make_add(2, 'S', 50,  1010000),
        make_execute(1, 50),
    });

    itch::OrderBook     map_book;
    itch::OrderBookFlat flat_book(990000, 1020000);

    auto apply = [&](auto& book) {
        itch::MessageVisitor v;
        v.on_add     = [&](const itch::AddOrder& m)     { book.add(m.order_ref, m.side, m.price, m.shares); };
        v.on_execute = [&](const itch::ExecuteOrder& m)  { book.execute(m.order_ref, m.executed_shares); };
        v.on_delete  = [&](const itch::DeleteOrder& m)   { book.del(m.order_ref); };
        v.on_replace = [&](const itch::ReplaceOrder& m)  { book.replace(m.old_order_ref, m.new_order_ref, m.shares, m.price); };
        return itch::parse_buffer(buf.data(), buf.size(), v);
    };

    apply(map_book);
    apply(flat_book);

    auto tob_map  = map_book.top_of_book();
    auto tob_flat = flat_book.top_of_book();

    ASSERT_EQ(tob_map.best_bid.has_value(), tob_flat.best_bid.has_value());
    if (tob_map.best_bid) {
        EXPECT_EQ(tob_map.best_bid->price_raw, tob_flat.best_bid->price_raw);
        EXPECT_EQ(tob_map.best_bid->shares,    tob_flat.best_bid->shares);
    }
    ASSERT_EQ(tob_map.best_ask.has_value(), tob_flat.best_ask.has_value());
    if (tob_map.best_ask) {
        EXPECT_EQ(tob_map.best_ask->price_raw, tob_flat.best_ask->price_raw);
        EXPECT_EQ(tob_map.best_ask->shares,    tob_flat.best_ask->shares);
    }
}

